// generate-companion-sbom.mjs — build a CycloneDX 1.6 SBOM for the postgres
// companion artifact by parsing its OWN repo/Packages index (ADR-0070 D5,
// T-129b). No new scanner: repo/Packages is generated by the companion's own
// build (fetch-postgres.sh / dpkg-scanpackages) and already carries
// Package/Version/SHA256/Filename per entry — exactly what CycloneDX needs,
// generated by the companion's own build rather than a third-party scan.
//
// Only the "deb" (apt) package index is parsed today. The default OS set
// also includes an rpm-format companion (rocky9); that format is refused
// LOUDLY here rather than silently emitting an empty or wrong SBOM — an rpm
// parser is a separate follow-up (recorded, not this ticket's scope: only
// the ubuntu2404 companion is actually built as of T-129b).
//
// Usage: node generate-companion-sbom.mjs --packages <repo/Packages> --name <n> --output <out>
import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";

function argVal(flag, required = false) {
  const i = process.argv.indexOf(flag);
  if (i === -1 || i === process.argv.length - 1) {
    if (required) {
      console.error(`generate-companion-sbom: missing required ${flag}`);
      process.exit(2);
    }
    return undefined;
  }
  return process.argv[i + 1];
}

const packagesPath = argVal("--packages", true);
const name = argVal("--name", true);
const outPath = argVal("--output", true);

let raw;
try {
  raw = readFileSync(packagesPath, "utf8");
} catch (e) {
  console.error(`generate-companion-sbom: cannot read ${packagesPath}: ${e.message}`);
  process.exit(1);
}

// deb822 stanzas, separated by one-or-more blank lines; fields may continue
// on following lines that start with whitespace (e.g. multi-line Description).
const stanzas = raw
  .split(/\r?\n\r?\n+/)
  .map((s) => s.trim())
  .filter(Boolean);

const components = [];
for (const stanza of stanzas) {
  const fields = {};
  let lastKey = null;
  for (const line of stanza.split(/\r?\n/)) {
    if (/^[ \t]/.test(line) && lastKey) {
      fields[lastKey] += "\n" + line;
      continue;
    }
    const m = line.match(/^([A-Za-z0-9-]+):\s?(.*)$/);
    if (!m) continue;
    fields[m[1]] = m[2];
    lastKey = m[1];
  }
  const pkg = fields.Package;
  const ver = fields.Version;
  const sha256 = fields.SHA256;
  if (!pkg || !ver) continue; // not a package stanza (shouldn't happen in a real index)
  const purl = `pkg:deb/ubuntu/${encodeURIComponent(pkg)}@${encodeURIComponent(ver)}`;
  const comp = { "bom-ref": `${pkg}@${ver}`, type: "library", name: pkg, version: ver, purl };
  if (sha256) comp.hashes = [{ alg: "SHA-256", content: sha256 }];
  components.push(comp);
}

if (components.length === 0) {
  console.error(
    `generate-companion-sbom: parsed 0 package stanzas from ${packagesPath} — refusing to emit an empty SBOM (is this a deb index? PKG_KIND must be "deb")`,
  );
  process.exit(1);
}

const h = createHash("sha256")
  .update(`${name}|${components.map((c) => c.purl).sort().join(",")}`)
  .digest("hex");
const serial = `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`;

const bom = {
  bomFormat: "CycloneDX",
  specVersion: "1.6",
  serialNumber: `urn:uuid:${serial}`,
  version: 1,
  metadata: {
    timestamp: "1970-01-01T00:00:00Z", // deterministic; see merge-sbom.mjs for the rationale
    component: { type: "application", "bom-ref": `bundle:${name}`, name, version: "n/a" },
  },
  components,
};

writeFileSync(outPath, JSON.stringify(bom, null, 2) + "\n");
console.log(
  `generate-companion-sbom: wrote ${outPath} — ${components.length} deb package components (from ${packagesPath})`,
);
